using NUnit.Framework;
using System.Collections.Generic;

[TestFixture]
public class FindMostFrequentTests
{
    [Test]
    public void Returns_Most_Frequent_Number()
    {
        var result = FindMostFrequent(new[] { 4, 1, 4, 2, 4, 2 });
        Assert.That(result, Is.EqualTo(4));
    }

    private int FindMostFrequent(int[] nums)
    {
        var counts = new Dictionary<int, int>();
        int bestValue = nums[0];
        int bestCount = 0;

        foreach (var num in nums)
        {
            counts[num] = counts.GetValueOrDefault(num) + 1;

            if (counts[num] > bestCount)
            {
                bestCount = counts[num];
                bestValue = num;
            }
        }

        return bestValue;
    }
}
